script:
const targetUrl = 'https://example.com';
const {targetInfos} = await cdp('Target.getTargets');
let page = targetInfos.find(t => t.type === 'page' && (t.url === targetUrl || t.url.startsWith(targetUrl)));
if (!page) {
  page = targetInfos.find(t => t.type === 'page');
}
if (!page) {
  throw new Error('No Chrome page target found');
}
const session = await cdp('Target.attachToTarget', {targetId: page.targetId, flatten: true});
const sessionId = session.sessionId;
await cdp('Page.enable', {}, {sessionId});
await cdp('Runtime.enable', {}, {sessionId});
await cdp('Page.navigate', {url: targetUrl}, {sessionId});
await new Promise(resolve => setTimeout(resolve, 1500));
const evalResult = await cdp('Runtime.evaluate', {
  expression: 'document.title',
  returnByValue: true
}, {sessionId});
const title = evalResult?.result?.value;
if (!title) throw new Error('Could not read page title');
return {title};
